71	    const title = '  ' + cp('中', LIMITS.title) + ' ';
72	    const description = '标题上限的说明\n第二行 😀';
73	    const scenario = '场景 🌙';
74	    assert.equal(points(title.trim()), LIMITS.title);
75	
76	    const { status, data } = await createIdea({ title, description, scenario });
77	    assert.equal(status, 201);
78	    assert.equal(data.idea.title, title.trim());
79	    assert.equal(data.idea.description, description);
80	    assert.equal(data.idea.scenario, scenario);
81	
82	    const list = await listIdeas();
83	    assert.equal(list[0].id, data.idea.id);
84	    assert.deepEqual(list[0], data.idea);
85	  });
86	
87	  await t.test('详细说明恰好 5000 码点：通过，首尾空白与换行计入长度并原样保留', async () => {
88	    // 首尾各两个空白 + 中间换行 + 4995 个中文码点，合计 5000 码点
89	    const description = '  ' + cp('中', 4995) + '\n  ';
90	    assert.equal(points(description), LIMITS.description);
91	    const title = '正文上限标题';
92	
93	    const { status, data } = await createIdea({ title, description });
94	    assert.equal(status, 201);
95	    assert.equal(data.idea.title, title);
96	    assert.equal(data.idea.description, description);
97	    assert.equal(data.idea.scenario, '');
98	
99	    const list = await listIdeas();
100	    assert.equal(list[0].description, description);
101	  });
102	
103	  await t.test('使用场景恰好 1000 码点（含中文、表情、换行）：通过并原样保留', async () => {
104	    // 中文与单个 😀 各算一个码点
105	    const scenario = cp('中', 700) + cp('😀', 200) + cp('A', 98) + '\n\n';
106	    assert.equal(points(scenario), LIMITS.scenario);
107	    const description = '场景上限的说明';
108	
109	    const { status, data } = await createIdea({ title: '场景上限标题', description, scenario });
110	    assert.equal(status, 201);
111	    assert.equal(data.idea.scenario, scenario);
