118	test('长度按码点而非 UTF-16 码元或传输字节：表情与多码点文字的边界内容应被接受', async (t) => {
119	  await t.test('标题 119 个中文 + 单个 😀 = 120 码点（😀 占 2 个 UTF-16 码元、4 个字节）：通过', async () => {
120	    const title = cp('中', LIMITS.title - 1) + '😀';
