131	    const description = cp('😀', LIMITS.description);
132	    assert.equal(points(description), LIMITS.description);
133	    assert.ok(description.length === LIMITS.description * 2);
134	    assert.ok(Buffer.byteLength(description) === LIMITS.description * 4);
