148	    const combining = 'é';
149	    assert.deepEqual([flag, zwjEmoji, combining].map(points), [2, 3, 2]);
150	    const title = flag + zwjEmoji + combining + cp('中', 113);
151	    assert.equal(points(title), 120);
152	    // 场景：997 个中文 + 旗帜（2 码点）+ 😀（1 码点）= 1000 码点
153	    const scenario = cp('中', 997) + flag + '😀';
154	    assert.equal(points(scenario), LIMITS.scenario);
155	
156	    const { status, data } = await createIdea({ title, description: '多码点文字说明', scenario });
157	    assert.equal(status, 201);
